#!/bin/sh
set -eu
umask 0077

SCRIPT_DIR=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
INSTALL_DIR=$(CDPATH= cd -- "$SCRIPT_DIR/.." && pwd)
ENV_FILE="$INSTALL_DIR/install.env"

if [ ! -f "$ENV_FILE" ]; then
  echo "安装配置缺失：$ENV_FILE" >&2
  exit 1
fi

# install.env is generated by the installer and is not user-editable settings.
. "$ENV_FILE"

URL="http://127.0.0.1:$PORT/"
mkdir -p "$DATA_DIR/logs"

health() {
  "$INSTALL_DIR/runtime/node" -e "
    fetch('${URL}healthz', { signal: AbortSignal.timeout(1800) })
      .then(async r => {
        const text = await r.text();
        if (!text.includes('\"service\":\"tianping-video-verification\"')) process.exit(1);
      })
      .catch(() => process.exit(1));
  " >/dev/null 2>&1
}

wait_for_service() {
  count=0
  while [ "$count" -lt 90 ]; do
    if health; then
      echo "系统已启动：$URL"
      return 0
    fi
    count=$((count + 1))
    sleep 0.5
  done
  echo "系统未能在 45 秒内启动。日志：$DATA_DIR/logs/server.log" >&2
  return 1
}

manual_pid() {
  if [ -f "$DATA_DIR/tianping.pid" ]; then
    cat "$DATA_DIR/tianping.pid"
  fi
}

manual_running() {
  pid=$(manual_pid)
  [ -n "$pid" ] && kill -0 "$pid" 2>/dev/null
}

manual_start() {
  if manual_running; then
    return 0
  fi
  mkdir -p "$DATA_DIR/logs"
  cd "$INSTALL_DIR/app"
  if command -v setsid >/dev/null 2>&1; then
    nohup setsid env \
      NODE_ENV=production \
      NODE_NO_WARNINGS=1 \
      TZ=Asia/Shanghai \
      HOST="$HOST" \
      PORT="$PORT" \
      DATA_DIR="$DATA_DIR" \
      FFMPEG_PATH="$INSTALL_DIR/runtime/bin/ffmpeg" \
      FFPROBE_PATH="$INSTALL_DIR/runtime/bin/ffprobe" \
      PDF_FONT_PATH="$INSTALL_DIR/runtime/fonts/NotoSansCJKsc-VF.ttf" \
      "$INSTALL_DIR/runtime/node" "$INSTALL_DIR/app/server.js" \
      >>"$DATA_DIR/logs/server.log" 2>&1 &
  else
    nohup env \
      NODE_ENV=production \
      NODE_NO_WARNINGS=1 \
      TZ=Asia/Shanghai \
      HOST="$HOST" \
      PORT="$PORT" \
      DATA_DIR="$DATA_DIR" \
      FFMPEG_PATH="$INSTALL_DIR/runtime/bin/ffmpeg" \
      FFPROBE_PATH="$INSTALL_DIR/runtime/bin/ffprobe" \
      PDF_FONT_PATH="$INSTALL_DIR/runtime/fonts/NotoSansCJKsc-VF.ttf" \
      "$INSTALL_DIR/runtime/node" "$INSTALL_DIR/app/server.js" \
      >>"$DATA_DIR/logs/server.log" 2>&1 &
  fi
  pid=$!
  printf '%s\n' "$pid" >"$DATA_DIR/tianping.pid"
}

manual_stop() {
  pid=$(manual_pid)
  if [ -z "$pid" ] || ! kill -0 "$pid" 2>/dev/null; then
    rm -f "$DATA_DIR/tianping.pid"
    return 0
  fi
  kill -TERM "-$pid" 2>/dev/null || kill -TERM "$pid" 2>/dev/null || true
  count=0
  while kill -0 "$pid" 2>/dev/null && [ "$count" -lt 80 ]; do
    count=$((count + 1))
    sleep 0.1
  done
  if kill -0 "$pid" 2>/dev/null; then
    kill -KILL "-$pid" 2>/dev/null || kill -KILL "$pid" 2>/dev/null || true
  fi
  rm -f "$DATA_DIR/tianping.pid"
}

systemd_call() {
  if [ "$SERVICE_MODE" = "systemd-user" ]; then
    systemctl --user "$@"
  else
    systemctl "$@"
  fi
}

start_service() {
  case "$SERVICE_MODE" in
    systemd-user)
      if ! systemd_call start "$SERVICE_NAME"; then
        echo "systemd 用户服务不可用，改用内置进程管理。"
        SERVICE_MODE=manual
        temp_env="$ENV_FILE.tmp.$$"
        sed "s/^SERVICE_MODE=.*/SERVICE_MODE='manual'/" "$ENV_FILE" >"$temp_env"
        mv "$temp_env" "$ENV_FILE"
        manual_start
      fi
      ;;
    systemd-system) systemd_call start "$SERVICE_NAME" ;;
    *) manual_start ;;
  esac
  wait_for_service
}

stop_service() {
  case "$SERVICE_MODE" in
    systemd-user|systemd-system) systemd_call stop "$SERVICE_NAME" || true ;;
    *) manual_stop ;;
  esac
}

status_service() {
  if health; then
    echo "运行中：$URL"
    exit 0
  fi
  case "$SERVICE_MODE" in
    systemd-user|systemd-system) systemd_call status --no-pager "$SERVICE_NAME" || true ;;
  esac
  echo "未运行"
  exit 1
}

show_password() {
  password_file="$DATA_DIR/initial-password.txt"
  if [ -f "$password_file" ]; then
    printf '\n'
    sed -n '1,5p' "$password_file"
    printf '\n首次登录账号：U000 / U001 / U002 / U003\n'
  fi
}

open_browser() {
  start_service
  if command -v xdg-open >/dev/null 2>&1; then
    xdg-open "$URL" >/dev/null 2>&1 &
  else
    echo "请在浏览器打开：$URL"
  fi
  show_password
}

case "${1:-start}" in
  start) start_service; show_password ;;
  stop) stop_service; echo "系统已停止" ;;
  restart)
    stop_service
    sleep 1
    start_service
    show_password
    ;;
  status) status_service ;;
  open) open_browser ;;
  *)
    echo "用法：$0 start|stop|restart|status|open" >&2
    exit 2
    ;;
esac
